import { FACES, KIT_EXPRESSIONS } from './kit/body.js';
import { language, nameIn, t } from './i18n.js';

const MOTIONS = { stand: '站起', jump: '跳跃', hop: '小跳', look: '张望', turn: '转身', nod: '点头',
  shake: '摇头', spin: '转圈', sit: '坐下', sleep: '睡觉', dizzy: '晕眩', walk: '走路', run: '跑步',
  wave: '招手', bow: '鞠躬', shiver: '发抖', flap: '扑翅膀', dance: '跳舞' };
const KITS = new Set(['coo', 'whale', 'minduck-duck', 'minduck-suit-duck']);
const first = value => Array.isArray(value) ? value[0] : value;

/** Actual factory words supplement the model-facing manifest only inside the local preview. */
export function previewActions(pack, words = [], capabilities = {}) {
  const declared = new Map((pack?.vocab ?? []).map(word => [word.id, word]));
  const supported = new Set(words);
  const ids = [...new Set([...declared.keys(), ...supported])].filter(id => supported.has(id));
  const actions = [{ id: 'auto', group: 'auto', label: t('dress.previewAuto'), type: 'auto' }];
  for (const word of ids) {
    const entry = declared.get(word);
    const fallback = language().startsWith('zh') ? MOTIONS[word] ?? FACES[word]?.label : '';
    actions.push({ id: `word:${word}`, type: 'word', word,
      group: entry ? 'figure' : KIT_EXPRESSIONS.includes(word) ? 'expression' : 'motion',
      label: first(nameIn(entry?.names)) || fallback || word.replace(/^./, c => c.toUpperCase()) });
  }
  for (const [kind, word] of [['work', 'work'], ['ask', 'ask'], ['success', 'happy'], ['error', 'sad']]) {
    if (supported.has(word)) actions.push({ id: `task:${kind}`, type: 'task', kind, group: 'task',
      label: t(`dress.previewTask.${kind}`) });
  }
  if (capabilities.pointer) {
    for (const kind of ['thinking', 'grab', ...(capabilities.drop ? ['drop'] : []), 'throw']) {
      actions.push({ id: `interaction:${kind}`, type: 'interaction', kind, group: 'interaction',
        seconds: pack?.vocab?.find(word => word.id === 'think')?.seconds ?? 6,
        label: t(`dress.previewInteraction.${kind}`) });
    }
  }
  if (capabilities.talk) actions.push({ id: 'state:talk', type: 'talk', group: 'interaction', label: t('dress.previewTalk') });
  if (capabilities.set && KITS.has(pack?.id)) {
    actions.push({ id: 'state:listening', type: 'listening', group: 'interaction', label: t('dress.previewListening') });
  }
  return actions;
}

function interact(body, kind, bounds) {
  const point = body.layout?.hit?.[0];
  if (!point) return false;
  const now = performance.now(), p = { x: point.x, y: point.y, t: now };
  body.pointer('down', p);
  if (kind === 'thinking') body.pointer('up', { ...p, t: now + 90 });
  else {
    body.pointer('move', { x: p.x + 12, y: p.y - 24, t: now + 40 });
    if (kind === 'drop') body.drop({ x: p.x, y: Math.max(10, bounds.floorY - 180) });
    if (kind === 'throw') {
      body.pointer('move', { x: p.x + 62, y: p.y - 28, t: now + 80 });
      body.pointer('up', { x: p.x + 102, y: p.y - 20, t: now + 120 });
    }
  }
  return true;
}

/** No private animation clock or persistence: the existing dress frame drives this player. */
export function createPreviewPlayer(body, action, bounds) {
  let started = false, elapsed = 0, quietAt = 0, talkAt = 0;
  body.set({ roam: action.type === 'auto' ? 'calm' : 'off' });
  return {
    step(dt) {
      if (action.type === 'auto' || !(dt > 0 && Number.isFinite(dt))) return;
      elapsed += dt;
      if (!started) {
        if (action.type === 'interaction' && !interact(body, action.kind, bounds())) return;
        if (action.type === 'word') body.do(action.word);
        if (action.type === 'task') body.set({ matterActivity: {
          kind: action.kind, id: `preview-${action.kind}`, expiresAt: Date.now() + 86400000 } });
        if (action.type === 'listening') body.set({ listening: true });
        started = true;
      }
      // A click starts the real shared thinking view, which needs its own hold to remain authoritative.
      const thinking = action.type === 'interaction' && action.kind === 'thinking' && elapsed < action.seconds + .5;
      if (!thinking && elapsed >= quietAt) { body.set({ hold: 2 }); quietAt = elapsed + 1; }
      if (action.type === 'talk' && elapsed >= talkAt) { body.talk(); talkAt = elapsed + .15; }
    },
  };
}
